import { Order } from "../domain/Order";
import { OrderRepository } from "../domain/OrderRepository";
import { createOrderLine } from "../domain/OrderLine";
import { StockService } from "../domain/StockService";
import { IdGenerator } from "./IdGenerator";
import { OrderDto, OrderLineDto, toOrderDto } from "./OrderDto";

export class PlaceOrderUseCase {
  constructor(
    private readonly orders: OrderRepository,
    private readonly stock: StockService,
    private readonly ids: IdGenerator,
  ) {}

  execute(requested: readonly OrderLineDto[]): OrderDto {
    const lines = requested.map((line) => createOrderLine(line.productId, line.quantity));
    const order = Order.place(this.ids.next(), lines);
    this.stock.reserve(order.lines);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

